{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello, आपको Symphony Industrial Air Cooler की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "हाँ कितने रुपये मिलेगा?"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "बहुत बढ़िया price आप seller से discuss कर सकते हैं।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "आपको कितने piece चाहिए होंगे?"
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "हमको एक ही चीज चाहिए room के लिए अपना अपना family के लिए personal के लिए।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "आपको सिर्फ एक piece चाहिए अपने room और family के लिए।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "चलिए अब air flow में क्या पसंद करेंगे?"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "18000 CFM या 25000 CFM या कुछ और?"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "अरे Madam मेरे को English नहीं आता हिंदी में बोलोगे तो मालूम पड़ेगा मेरे को।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "बिल्कुल मैं हिंदी में ही बात करूंगी।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "आपको air flow में कौन सा चाहिए?"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "18000 CFM या 25000 CFM या कुछ और?"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "नहीं ये दस हजार का दिखता ना।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "आपने 10,000 piece बताया।"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "अब बताइए कितने square feet के area के लिए चाहिए?"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "जैसे 2,000 square feet, 1,500 square feet या कुछ और?"
    },
    {
      "i": 20,
      "speaker": "caller",
      "text": "आपने दस हज़ार piece में"
    },
    {
      "i": 21,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "आपके यहाँ सबसे छोटा माल कितना क्या?"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "बहुत बढ़िया seller आपको सबसे छोटा model और उसकी price बता देंगे।"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "area कितना square feet का है आपके कमरे का?"
    },
    {
      "i": 25,
      "speaker": "caller",
      "text": "हमारा होएगा बीस foot।"
    },
    {
      "i": 26,
      "speaker": "bot",
      "text": "ठीक है 20 foot का area note कर लिया।"
    },
    {
      "i": 27,
      "speaker": "bot",
      "text": "अब एक minute दीजिए मैं आपकी details check करती हूं।"
    },
    {
      "i": 28,
      "speaker": "caller",
      "text": "Okay."
    },
    {
      "i": 29,
      "speaker": "bot",
      "text": "आप अपनी city और state भी बता दीजिए please."
    }
  ]
}
